package dev.raven.backup;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class ExternalTarTest {
 static void text(byte[] h,int at,int length,String v){byte[] b=v.getBytes(StandardCharsets.US_ASCII);System.arraycopy(b,0,h,at,Math.min(length,b.length));}
 static void entry(ByteArrayOutputStream out,String name,char type,String value)throws Exception{byte[] data=value.getBytes(StandardCharsets.UTF_8),h=new byte[512];text(h,0,100,name);text(h,100,8,"0000755");text(h,108,8,"0023420");text(h,116,8,"0023420");text(h,124,12,String.format(Locale.ROOT,"%011o",data.length));text(h,136,12,"00000000000");Arrays.fill(h,148,156,(byte)32);h[156]=(byte)type;text(h,257,6,"ustar");text(h,263,2,"00");long sum=0;for(byte b:h)sum+=b&255;text(h,148,6,String.format(Locale.ROOT,"%06o",sum));h[154]=0;h[155]=32;out.write(h);out.write(data);out.write(new byte[(512-data.length%512)%512]);}
 static byte[] tar(String name,char type)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();entry(out,"./",'5',"");entry(out,name,type,type=='0'?"fixture external bytes":"");out.write(new byte[1024]);return out.toByteArray();}
 static void bad(byte[] bytes)throws Exception{try{ExternalTar.scan(new ByteArrayInputStream(bytes),null);}catch(IOException expected){if(!BackupIssues.invalidPayload(expected))throw new AssertionError("validation failure is not tagged",expected);return;}throw new AssertionError("Unsafe TAR accepted");}
 public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory(Paths.get(args[0]),"external-parser-");byte[] valid=tar("./marker",'0');Path stage=Files.createDirectory(root.resolve("stage"));ExternalTar.read(new ByteArrayInputStream(valid),valid.length,BackupEngine.digest(valid),stage);if(!new String(Files.readAllBytes(stage.resolve("marker")),StandardCharsets.UTF_8).equals("fixture external bytes"))throw new AssertionError("content");
 bad(tar("../escape",'0'));bad(tar("./link",'2'));byte[] header=valid.clone();header[0]^=1;bad(header);try{ExternalTar.read(new ByteArrayInputStream(valid),valid.length,String.join("",Collections.nCopies(64,"0")),null);throw new AssertionError("bad digest accepted");}catch(ExternalTar.InvalidData expected){if(!BackupIssues.invalidPayload(expected))throw new AssertionError("digest tag");}
 if(BackupIssues.invalidPayload(new IOException("Free more internal storage")))throw new AssertionError("space error marked as corrupt");System.out.println("PASS one-pass external extraction/hash, traversal/link/header rejection and corrupt-payload tags without mislabeling storage errors");}
}
